import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Zendure Manager","description":"Operating modes and performance control of the Zendure Manager.","frontmatter":{"title":"Zendure Manager","description":"Operating modes and performance control of the Zendure Manager."},"headers":[],"relativePath":"en/collection/zendure-ha/manager.md","filePath":"en/collection/zendure-ha/manager.md","lastUpdated":1793198184000}'),o={name:"en/collection/zendure-ha/manager.md"};function i(d,e,s,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<p><a id="current-focus"></a></p><h1 id="zendure-manager" tabindex="-1">Zendure Manager <a class="header-anchor" href="#zendure-manager" aria-label="Permalink to &quot;Zendure Manager {#zendure-manager}&quot;">​</a></h1><p>The Zendure Manager tries to regulate the P1/house consumption sensor towards <code>0 W</code> via the Zendure devices. To do this, it controls the charging and discharging performance of the devices.</p><div class="warning custom-block"><p class="custom-block-title">HEMS and app programs</p><p>If Zendure Manager and HEMS or a power program in the Zendure app are controlling at the same time, they can work against each other. Only use an active control strategy.</p></div><h2 id="p1-sensor" tabindex="-1">P1 sensor <a class="header-anchor" href="#p1-sensor" aria-label="Permalink to &quot;P1 sensor {#p1-sensor}&quot;">​</a></h2><p>The P1 sensor should provide home consumption:</p><ul><li>positive value: house consumes mains electricity</li><li>negative value: house feeds in</li></ul><p>This sensor is the basis for Smart Matching.</p><h2 id="betriebsarten" tabindex="-1">Operating modes <a class="header-anchor" href="#betriebsarten" aria-label="Permalink to &quot;Operating modes {#betriebsarten}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Aus</code></td><td>Manager does not control devices</td></tr><tr><td><code>Manuelle Leistungsregelung</code></td><td>fixed power value via <code>Manuelle Leistung</code></td></tr><tr><td><code>Smarte Leistungsregelung</code></td><td>tries to keep the P1 sensor at 0W</td></tr><tr><td><code>Smartes nur Entladen</code></td><td>like Smart Matching, but without loading</td></tr><tr><td><code>Smartes nur Laden</code></td><td>only charges, does not discharge</td></tr><tr><td><code>Solar speichern</code></td><td>stores solar/offgrid input preferably in batteries</td></tr></tbody></table><h2 id="manuelle-leistung" tabindex="-1">Manual performance <a class="header-anchor" href="#manuelle-leistung" aria-label="Permalink to &quot;Manual performance {#manuelle-leistung}&quot;">​</a></h2><p>For <code>Manuelle Leistungsregelung</code>, the entity <code>Manuelle Leistung</code> determines how much power should be fed in or out.</p><ul><li>positive value: battery discharges towards house/grid</li><li>negative value: Battery charges if the device supports AC charging</li></ul><h2 id="smart-matching" tabindex="-1">Smart matching <a class="header-anchor" href="#smart-matching" aria-label="Permalink to &quot;Smart matching {#smart-matching}&quot;">​</a></h2><p>With Smart Matching, the manager distributes power to the available devices. Fuse group, charge level, minimum SoC, maximum performance and device status all play a role.</p><p>The original wiki describes the distribution logic as partially outdated. Therefore, this page should be seen as a guide and checked against the current code if necessary.</p><p>Original wiki:</p><ul><li><a href="https://github.com/Zendure/Zendure-HA/wiki/Function-description" target="_blank" rel="noreferrer">Function description</a></li><li><a href="https://github.com/Zendure/Zendure-HA/wiki/Power-distribution-strategy" target="_blank" rel="noreferrer">Power distribution strategy</a></li></ul>',18)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
